// DELETE /v1/webhook_endpoints/{id}
//
// https://fiscalisto.com/docs/api/referencia/webhooks/delete-webhook-endpoint
func (s *WebhookEndpointsService) Delete(ctx context.Context, id string, opts ...RequestOption) (*Deleted, error) {
	out := new(Deleted)
	if err := s.c.do(ctx, "DELETE", "/v1/webhook_endpoints/"+url.PathEscape(id), nil, nil, false, out, opts); err != nil {
		return nil, err
	}
	return out, nil
}

// RollSecret: Cambiar el secreto
//
// Un secreto nuevo, que la respuesta trae una sola vez. El anterior sigue firmando (una segunda firma en webhook-signature) el tiempo que elija, 24 horas por omisión, para que cambie su servidor sin rechazar eventos. Si se filtró, mande previous_secret_expires_in: 0.
//
// POST /v1/webhook_endpoints/{id}/roll_secret
//
// https://fiscalisto.com/docs/api/referencia/webhooks/roll-webhook-secret
func (s *WebhookEndpointsService) RollSecret(ctx context.Context, id string, params *RollWebhookSecretParams, opts ...RequestOption) (*WebhookEndpoint, error) {
	out := new(WebhookEndpoint)
	if err := s.c.do(ctx, "POST", "/v1/webhook_endpoints/"+url.PathEscape(id)+"/roll_secret", params, nil, false, out, opts); err != nil {
		return nil, err
	}
	return out, nil
}

// Test: Mandar un evento de prueba
//
// Manda ahora, una sola vez y sin reintentos, un evento del tipo que elija con un objeto de ejemplo (sus id no existen), firmado como los reales, aunque el webhook no escuche ese tipo. La respuesta trae lo que contestó su servidor. El evento no sale en GET /v1/events, pero sí en las entregas del webhook.
//
// POST /v1/webhook_endpoints/{id}/test
//
// https://fiscalisto.com/docs/api/referencia/webhooks/test-webhook-endpoint
func (s *WebhookEndpointsService) Test(ctx context.Context, id string, params *TestWebhookEndpointParams, opts ...RequestOption) (*WebhookTest, error) {
	out := new(WebhookTest)
	if err := s.c.do(ctx, "POST", "/v1/webhook_endpoints/"+url.PathEscape(id)+"/test", params, nil, false, out, opts); err != nil {
		return nil, err
	}
	return out, nil
}

// EventsService: Eventos (client.Events).
type EventsService struct{ c *Client }

// List: Listar eventos
//
// Los de los últimos 30 días, los más recientes primero.
//
// GET /v1/events
//
// https://fiscalisto.com/docs/api/referencia/eventos/list-events
func (s *EventsService) List(ctx context.Context, params *ListEventsParams, opts ...RequestOption) (*Page[Event], error) {
	return list[Event](ctx, s.c, "/v1/events", params, "", opts)
}

// ListAutoPaging: Listar eventos, todos, página por página: for x, err := range …
func (s *EventsService) ListAutoPaging(ctx context.Context, params *ListEventsParams, opts ...RequestOption) iter.Seq2[Event, error] {
	return listAll[Event](ctx, s.c, "/v1/events", params, opts)
}

// Get: Ver un evento
//
// GET /v1/events/{id}
//
// https://fiscalisto.com/docs/api/referencia/eventos/get-event
func (s *EventsService) Get(ctx context.Context, id string, opts ...RequestOption) (*Event, error) {
	out := new(Event)
	if err := s.c.do(ctx, "GET", "/v1/events/"+url.PathEscape(id), nil, nil, false, out, opts); err != nil {
		return nil, err
	}
	return out, nil
}
